import fs from "fs";
import { GetStaticProps } from "next";
import Link from "next/link";
import path from "path";

type BlogPost = {
  slug: string;
  metadata: {
    title: string;
    date: string;
    description: string;
    author: string;
  };
};

type BlogIndexProps = {
  posts: BlogPost[];
};

export const getStaticProps: GetStaticProps<BlogIndexProps> = async () => {
  const postsDirectory = path.join(process.cwd(), "pages/blog");
  const filenames = fs.readdirSync(postsDirectory);

  const posts = filenames
    .filter((filename) => filename.endsWith(".mdx"))
    .filter((filename) => filename !== "index.tsx")
    .map((filename) => {
      const slug = filename.replace(".mdx", "");
      // Import the metadata from the MDX file
      const { metadata } = require(`./${filename}`);
      return {
        slug,
        metadata,
      };
    })
    .sort(
      (a, b) =>
        new Date(b.metadata.date).getTime() -
        new Date(a.metadata.date).getTime()
    );

  return {
    props: {
      posts,
    },
  };
};

export default function BlogIndex({ posts }: BlogIndexProps) {
  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <h1 className="text-4xl font-bold mb-8">Blog Posts</h1>
      <div className="space-y-8">
        {posts.map((post) => (
          <article key={post.slug} className="border-b pb-8">
            <Link
              href={`/blog/${post.slug}`}
              className="block hover:text-blue-600 transition-colors"
            >
              <h2 className="text-2xl font-bold mb-2">{post.metadata.title}</h2>
              <div className="text-gray-600 mb-2">
                <time>{post.metadata.date}</time> • {post.metadata.author}
              </div>
              <p className="text-gray-700">{post.metadata.description}</p>
            </Link>
          </article>
        ))}
      </div>
    </div>
  );
}
